# Add debug to scan
def scan(grid, grid_vis, start_r, start_c, target):
    comp = []
    stack = [(start_r, start_c)]
    iteration = 0
    while stack:
        iteration += 1
        r, c = stack.pop()
        msg = f"scan: ({r},{c}), grid shape check"
        try:
            rev = len(grid) if grid else 0
            revc = len(grid[0]) if r < rev else 0
            msg += f" rows={rev}, c_limit={revc}"
        except:
            msg += f" ERROR getting grid dimensions"
        print(msg)
        if r < 0 or r >= 16 or c < 0 or c >= 27:
            continue
        if grid_vis[r][c]:
            continue
        if r >= 0 and r < len(grid) and c >= 0 and c < len(grid[r]):
            if grid[r][c] != target:
                continue
            grid_vis[r][c] = True
            comp.append((r, c))
            stack.extend([(r-1,c), (r+1,c), (r,c-1), (r,c+1)])

    print(f"scan done, comp size={len(comp)}")
    return comp

